CREATE FUNCTION public.fn_an_thong_tin_nguoi_dan() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF NEW.TrangThaiPhanAnh = 'ChuaXuLy' THEN
        UPDATE NguoiDung
        SET BaoMatThongTin = TRUE
        WHERE CCCD = NEW.CCCD;
    END IF;
    RETURN NEW;
END;
$$;


