--
-- TOC entry 251 (class 1255 OID 44974)
-- Name: fn_cap_nhat_trang_thai_phan_anh(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_cap_nhat_trang_thai_phan_anh() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    ma_phan_anh INT;
BEGIN
    -- Lấy mã phản ánh từ box chat
    SELECT MaPhanAnh INTO ma_phan_anh
    FROM BoxChat
    WHERE MaBoxChat = NEW.MaBoxChat;

    -- Nếu người gửi là cán bộ → đổi trạng thái phản ánh
    IF EXISTS (
        SELECT 1 FROM NguoiDung
        WHERE CCCD = NEW.NguoiGui AND VaiTro = 'CanBo'
    ) THEN
        UPDATE PhanAnh
        SET TrangThaiPhanAnh = 'DangXuLy'
        WHERE MaPhanAnh = ma_phan_anh;
    END IF;

    RETURN NEW;
END;
$$;


ALTER FUNCTION public.fn_cap_nhat_trang_thai_phan_anh() OWNER TO postgres;

