-- TOC entry 269 (class 1255 OID 44981)
-- Name: sp_capnhattrangthaiphananh(integer, character varying); Type: PROCEDURE; Schema: public; Owner: postgres
--

CREATE PROCEDURE public.sp_capnhattrangthaiphananh(IN p_maphananh integer, IN p_trangthai character varying)
    LANGUAGE plpgsql
    AS $$
BEGIN
    -- Kiểm tra trạng thái hợp lệ
    IF p_trangthai NOT IN ('ChuaXuLy', 'DangXuLy', 'DaXuLy') THEN
        RAISE EXCEPTION 'Trạng thái không hợp lệ: %', p_trangthai;
    END IF;

    -- Cập nhật
    UPDATE PhanAnh
    SET TrangThaiPhanAnh = p_trangthai
    WHERE MaPhanAnh = p_maphananh;

    IF NOT FOUND THEN
        RAISE NOTICE 'Không tìm thấy phản ánh với mã %', p_maphananh;
    ELSE
        RAISE NOTICE 'Đã cập nhật trạng thái phản ánh % thành %', p_maphananh, p_trangthai;
    END IF;
END;
$$;


ALTER PROCEDURE public.sp_capnhattrangthaiphananh(IN p_maphananh integer, IN p_trangthai character varying) OWNER TO postgres;

