-- TOC entry 257 (class 1255 OID 44980)
-- Name: sp_themphananh(character, integer, character varying, text, integer); Type: PROCEDURE; Schema: public; Owner: postgres
--

CREATE PROCEDURE public.sp_themphananh(IN p_cccd character, IN p_madiadi integer, IN p_loaiphananh character varying, IN p_mota text, IN p_matdinhkem integer DEFAULT NULL::integer)
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_maphananh INT;
BEGIN
    -- Kiểm tra người gửi tồn tại
    IF NOT EXISTS (SELECT 1 FROM NguoiDung WHERE CCCD = p_cccd) THEN
        RAISE EXCEPTION 'Người dùng với CCCD % không tồn tại', p_cccd;
    END IF;

    -- Thêm phản ánh mới
    VALUES (p_cccd, p_madiadi, p_loaiphananh, p_mota, p_matdinhkem, 'ChuaXuLy', CURRENT_TIMESTAMP)
    RETURNING MaPhanAnh INTO v_maphananh;

    -- Tạo box chat tương ứng để người dân và cán bộ trao đổi
    VALUES (v_maphananh);

    RAISE NOTICE 'Đã thêm phản ánh mã % và tạo box chat tương ứng.', v_maphananh;
END;
$$;


