CREATE FUNCTION public.update_comment_count() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF (TG_OP = 'INSERT') THEN
        UPDATE public.phananh SET comment_count = comment_count + 1 WHERE maphananh = NEW.maphananh;
    ELSIF (TG_OP = 'DELETE') THEN
        UPDATE public.phananh SET comment_count = comment_count - 1 WHERE maphananh = OLD.maphananh;
    END IF;
    RETURN NULL;
END;
$$;


