--
-- TOC entry 248 (class 1259 OID 45190)
-- Name: view_newsfeed; Type: VIEW; Schema: public; Owner: postgres
--

CREATE VIEW public.view_newsfeed AS
 SELECT p.maphananh,
    p.tieude,
    p.mota,
    p.loaiphananh,
    p.like_count,
    p.comment_count,
    p.view_count,
    p.thoigiantao,
    p.cccd,
    n.name AS nguoi_dang,
    n.avatar_url,
    d.xaphuong,
    d.chitiet AS diachi,
    v.tenvande,
    v.trangthai AS trangthai_vande,
    t.duongdan AS hinh_anh,
    ((((p.like_count * 2) + (p.comment_count * 3)))::numeric + ((p.view_count)::numeric * 0.1)) AS hot_score
   FROM ((((public.phananh p
     JOIN public.nguoidung n ON ((p.cccd = n.cccd)))
     LEFT JOIN public.diachi d ON ((p.madiachi = d.madiachi)))
     LEFT JOIN public.vande v ON ((p.mavande = v.mavande)))
     LEFT JOIN public.tepdinhkem t ON ((p.matepdinhkem = t.matepdinhkem)))
  WHERE (p.is_public = true);


ALTER VIEW public.view_newsfeed OWNER TO postgres;

