--
-- TOC entry 247 (class 1259 OID 45185)
-- Name: view_vande_summary; Type: VIEW; Schema: public; Owner: postgres
--

CREATE VIEW public.view_vande_summary AS
 SELECT v.mavande,
    v.tenvande,
    v.phanloai,
    v.trangthai,
    v.ketqua,
    v.ngaytao,
    v.ngaycapnhat,
    v.cccd_canbo_xuly,
    n.name AS ten_canbo_xuly,
    n.sdt AS sdt_canbo,
    count(p.maphananh) AS so_luong_phananh,
    count(DISTINCT p.cccd) AS so_nguoi_phananh,
    COALESCE(sum(p.like_count), (0)::bigint) AS tong_like,
    COALESCE(sum(p.comment_count), (0)::bigint) AS tong_comment,
    COALESCE(sum(p.view_count), (0)::bigint) AS tong_view,
        CASE
            WHEN ((v.trangthai)::text = 'DaGiaiQuyet'::text) THEN (EXTRACT(epoch FROM (v.ngaycapnhat - v.ngaytao)) / (86400)::numeric)
            ELSE NULL::numeric
        END AS so_ngay_xu_ly
   FROM ((public.vande v
     LEFT JOIN public.nguoidung n ON ((v.cccd_canbo_xuly = n.cccd)))
     LEFT JOIN public.phananh p ON ((v.mavande = p.mavande)))
  GROUP BY v.mavande, v.tenvande, v.phanloai, v.trangthai, v.ketqua, v.ngaytao, v.ngaycapnhat, v.cccd_canbo_xuly, n.name, n.sdt;


